"use client";

import { useEffect, useState, Suspense } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { useApp } from "@/context/AppContext";
import {
  User,
  LogOut,
  Mail,
  Calendar,
  ShoppingBag,
  Package,
  Phone,
  ChevronRight,
  Percent,
  MapPin,
  Edit,
} from "lucide-react";
import { api } from "@/services/api";
import { OrderRead, Currency } from "@/types";
import { formatCurrency } from "@/utils/currency";
import NovaPostWidget from "@/components/NovaPostWidget";
import Link from "next/link";

function ProfileContent() {
  const { isCustomerLoggedIn, logoutCustomer, currency } = useApp();
  const router = useRouter();
  const searchParams = useSearchParams();
  const tab = searchParams.get("tab") || "info";

  const [mounted, setMounted] = useState(false);
  const [customerInfo, setCustomerInfo] = useState<any>(null);
  const [orders, setOrders] = useState<OrderRead[]>([]);
  const [loading, setLoading] = useState(true);

  // Profile Edit State
  const [isEditing, setIsEditing] = useState(false);
  const [editFirstName, setEditFirstName] = useState("");
  const [editLastName, setEditLastName] = useState("");
  const [editPhone, setEditPhone] = useState("");
  const [editAddress, setEditAddress] = useState("");
  const [saveLoading, setSaveLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");

  useEffect(() => {
    setMounted(true);
    if (mounted && !isCustomerLoggedIn) {
      router.push("/login");
    }
  }, [isCustomerLoggedIn, router, mounted]);

  useEffect(() => {
    if (mounted && isCustomerLoggedIn) {
      const loadData = async () => {
        setLoading(true);
        try {
          const [info, ordersData] = await Promise.all([
            api.getMe(),
            api.getMyOrders(),
          ]);
          setCustomerInfo(info);
          setOrders(ordersData);
          setEditFirstName(info.first_name || "");
          setEditLastName(info.last_name || "");
          setEditPhone(info.phone || "");
          setEditAddress(info.default_address || "");
        } catch (err) {
          console.error("Failed to load profile data", err);
        } finally {
          setLoading(false);
        }
      };
      loadData();
    }
  }, [mounted, isCustomerLoggedIn]);

  const formatAddress = (addrString: string) => {
    if (!addrString) return "Не вказано";
    if (addrString.startsWith("{") && addrString.endsWith("}")) {
      try {
        const parsed = JSON.parse(addrString);
        const parts = [];
        if (parsed.city) parts.push(parsed.city);
        if (parsed.branch) parts.push(parsed.branch);
        if (parts.length > 0) return parts.join(", ");
      } catch (e) {
        // Fallback
      }
    }
    return addrString;
  };

  const handleSaveProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMsg("");
    setSaveLoading(true);
    try {
      const updated = await api.updateProfile({
        first_name: editFirstName,
        last_name: editLastName,
        phone: editPhone,
        default_address: editAddress,
      });
      setCustomerInfo(updated);
      setIsEditing(false);
    } catch (err: any) {
      console.error(err);
      setErrorMsg(err.message || "Не вдалося зберегти дані");
    } finally {
      setSaveLoading(false);
    }
  };

  if (!mounted || !isCustomerLoggedIn) {
    return null;
  }

  const handleLogout = () => {
    logoutCustomer();
    router.push("/");
  };

  const getStatusBadge = (status: string) => {
    const statusMap: Record<string, { label: string; color: string }> = {
      new: { label: "Нове", color: "bg-blue-100 text-blue-800" },
      processing: {
        label: "В обробці",
        color: "bg-yellow-100 text-yellow-800",
      },
      shipped: { label: "Відправлено", color: "bg-purple-100 text-purple-800" },
      delivered: { label: "Доставлено", color: "bg-green-100 text-green-800" },
      cancelled: { label: "Скасовано", color: "bg-red-100 text-red-800" },
    };
    const s = statusMap[status] || {
      label: status,
      color: "bg-gray-100 text-gray-800",
    };
    return (
      <span
        className={`px-2.5 py-0.5 rounded-full text-xs font-bold ${s.color}`}
      >
        {s.label}
      </span>
    );
  };

  return (
    <div className="animate-in fade-in duration-500">
      <div className="mb-8 flex flex-col md:flex-row md:items-center justify-between gap-4">
        <h1 className="text-2xl md:text-3xl font-bold text-slate-900 dark:text-white">
          Мій кабінет
        </h1>
        <div className="flex bg-white dark:bg-slate-800 p-1 rounded-lg shadow-sm border border-slate-100 dark:border-slate-700">
          <button
            onClick={() => router.push("/profile?tab=info")}
            className={`px-4 py-2 rounded-md text-sm font-bold transition ${tab === "info" ? "bg-blue-600 text-white shadow-sm" : "text-slate-600 dark:text-slate-300 hover:bg-gray-50 dark:hover:bg-slate-700"}`}
          >
            Особисті дані
          </button>
          <button
            onClick={() => router.push("/profile?tab=orders")}
            className={`px-4 py-2 rounded-md text-sm font-bold transition ${tab === "orders" ? "bg-blue-600 text-white shadow-sm" : "text-slate-600 dark:text-slate-300 hover:bg-gray-50 dark:hover:bg-slate-700"}`}
          >
            Мої замовлення
          </button>
        </div>
      </div>

      <div className="flex flex-col gap-8">
        {/* Main Content Area */}
        <div className="flex-grow">
          {loading ? (
            <div className="bg-white dark:bg-slate-800 shadow rounded-xl p-12 flex flex-col items-center justify-center border border-slate-100 dark:border-slate-700">
              <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mb-4"></div>
              <p className="text-slate-500 dark:text-slate-400 font-medium">
                Завантаження даних...
              </p>
            </div>
          ) : tab === "info" ? (
            <div className="bg-white dark:bg-slate-800 shadow rounded-xl overflow-hidden border border-slate-100 dark:border-slate-700 animate-in fade-in slide-in-from-bottom-4 duration-300">
              <div className="px-6 py-4 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-slate-50/50 dark:bg-slate-800/50">
                <h3 className="font-bold text-slate-800 dark:text-white">
                  Особиста інформація
                </h3>
                {!isEditing && (
                  <button
                    onClick={() => {
                      setEditFirstName(customerInfo?.first_name || "");
                      setEditLastName(customerInfo?.last_name || "");
                      setEditPhone(customerInfo?.phone || "");
                      setEditAddress(
                        formatAddress(customerInfo?.default_address),
                      );
                      setIsEditing(true);
                    }}
                    className="flex items-center gap-1.5 text-sm font-bold text-blue-600 dark:text-blue-400 hover:text-blue-700 transition"
                  >
                    <Edit size={16} />
                    Редагувати
                  </button>
                )}
              </div>

              {isEditing ? (
                <form
                  onSubmit={handleSaveProfile}
                  className="px-6 py-8 md:p-8 space-y-6"
                >
                  {errorMsg && (
                    <div className="p-4 bg-red-50 dark:bg-red-950/20 text-red-600 dark:text-red-400 rounded-xl text-sm font-semibold border border-red-100 dark:border-red-900/30">
                      {errorMsg}
                    </div>
                  )}

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {/* First Name Input */}
                    <div className="space-y-1.5">
                      <label className="text-xs font-bold text-slate-700 dark:text-slate-300 uppercase tracking-wider flex items-center gap-1.5">
                        <User size={14} className="text-slate-400" />
                        Ім'я
                      </label>
                      <input
                        type="text"
                        required
                        value={editFirstName}
                        onChange={(e) => setEditFirstName(e.target.value)}
                        className="rounded-xl block w-full px-4 py-3 border border-gray-300 dark:border-slate-700 text-slate-900 dark:text-white bg-white dark:bg-slate-900 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm transition-all"
                      />
                    </div>

                    {/* Last Name Input */}
                    <div className="space-y-1.5">
                      <label className="text-xs font-bold text-slate-700 dark:text-slate-300 uppercase tracking-wider flex items-center gap-1.5">
                        <User size={14} className="text-slate-400" />
                        Прізвище
                      </label>
                      <input
                        type="text"
                        required
                        value={editLastName}
                        onChange={(e) => setEditLastName(e.target.value)}
                        className="rounded-xl block w-full px-4 py-3 border border-gray-300 dark:border-slate-700 text-slate-900 dark:text-white bg-white dark:bg-slate-900 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm transition-all"
                      />
                    </div>

                    {/* Phone Input */}
                    <div className="space-y-1.5">
                      <label className="text-xs font-bold text-slate-700 dark:text-slate-300 uppercase tracking-wider flex items-center gap-1.5">
                        <Phone size={14} className="text-slate-400" />
                        Телефон
                      </label>
                      <input
                        type="text"
                        required
                        value={editPhone}
                        onChange={(e) => setEditPhone(e.target.value)}
                        className="rounded-xl block w-full px-4 py-3 border border-gray-300 dark:border-slate-700 text-slate-900 dark:text-white bg-white dark:bg-slate-900 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm transition-all"
                      />
                    </div>

                    {/* Address Input */}
                    <div className="space-y-1.5">
                      <label className="text-xs font-bold text-slate-700 dark:text-slate-300 uppercase tracking-wider flex items-center gap-1.5">
                        <MapPin size={14} className="text-slate-400" />
                        Адреса за замовчуванням (відділення Нової пошти)
                      </label>
                      <div className="mb-2">
                        {editAddress && (
                          <div className="text-sm text-slate-600 dark:text-slate-400 mb-2 p-3 bg-slate-50 dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700">
                            <strong>Поточна адреса:</strong>{" "}
                            {formatAddress(editAddress)}
                          </div>
                        )}
                      </div>
                      <NovaPostWidget
                        onSelect={(data) => {
                          const addressString = JSON.stringify({
                            city: data.city,
                            branch: data.description,
                            ref: data.ref,
                            fullAddress: data.address,
                          });
                          setEditAddress(addressString);
                        }}
                      />
                    </div>
                  </div>

                  <div className="flex justify-end gap-4 border-t border-slate-100 dark:border-slate-700 pt-6">
                    <button
                      type="button"
