"use client";

import { useState, Suspense, useEffect } from "react";
import { useSearchParams, useRouter } from "next/navigation";
import { api } from "@/services/api";

function VerifyForm() {
  const searchParams = useSearchParams();
  const router = useRouter();
  const token = searchParams.get("token");

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [status, setStatus] = useState<
    "idle" | "loading" | "success" | "error"
  >("idle");
  const [message, setMessage] = useState("");

  useEffect(() => {
    if (typeof window !== "undefined") {
      const stored = localStorage.getItem("registerEmail");
      if (stored) {
        setEmail(stored);
      }
    }
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (password !== confirmPassword) {
      setStatus("error");
      setMessage("Паролі не співпадають");
      return;
    }

    setStatus("loading");
    try {
      await api.verifyCustomer({
        token,
        password,
        confirm_password: confirmPassword,
      });
      setStatus("success");
      setTimeout(() => {
        router.push("/login");
      }, 3000);
    } catch (err: any) {
      setStatus("error");
      setMessage(err.message);
    }
  };

  if (!token) {
    return (
      <div className="max-w-md w-full space-y-8 bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700/50 p-10 rounded-xl shadow-lg dark:shadow-2xl/10 transition-colors duration-300 text-center">
        <h2 className="text-2xl font-bold text-red-600 dark:text-red-400">
          Помилка
        </h2>
        <p className="mt-2 text-slate-600 dark:text-slate-400">
          Токен підтвердження відсутній.
        </p>
      </div>
    );
  }

  return (
    <div className="max-w-md w-full space-y-8 bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700/50 p-10 rounded-xl shadow-lg dark:shadow-2xl/10 transition-colors duration-300">
      <div>
        <h2 className="mt-6 text-center text-3xl font-extrabold text-slate-900 dark:text-white transition-colors">
          Встановлення пароля
        </h2>
        <p className="mt-2 text-center text-sm text-slate-600 dark:text-slate-400 transition-colors">
          Придумайте надійний пароль для вашого акаунта
        </p>
      </div>

      {status === "success" ? (
        <div className="bg-green-50 dark:bg-green-950/30 border-l-4 border-green-400 dark:border-green-500 p-4 rounded-r-md transition-colors">
          <div className="flex">
            <div className="flex-shrink-0">
              <svg
                className="h-5 w-5 text-green-400 dark:text-green-500"
                fill="currentColor"
                viewBox="0 0 20 20"
              >
                <path
                  fillRule="evenodd"
                  d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z"
                  clipRule="evenodd"
                />
              </svg>
            </div>
            <div className="ml-3">
              <p className="text-sm text-green-700 dark:text-green-300 font-medium">
                Пароль успішно встановлено! Перенаправлення на сторінку входу...
              </p>
            </div>
          </div>
        </div>
      ) : (
        <form className="mt-8 space-y-6" onSubmit={handleSubmit}>
          {/* Hidden username field for browser password manager context */}
          <input
            type="text"
            name="username"
            autoComplete="username"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            className="hidden"
            aria-hidden="true"
          />

          <div className="rounded-md shadow-sm space-y-4">
            <div>
              <label htmlFor="password" className="sr-only">
                Новий пароль
              </label>
              <input
                id="password"
                name="password"
                type="password"
                autoComplete="new-password"
                required
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="appearance-none rounded-md relative block w-full px-3 py-2 border border-gray-300 dark:border-slate-700 placeholder-gray-500 dark:placeholder-slate-400 text-slate-900 dark:text-white bg-white dark:bg-slate-900 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 sm:text-sm transition-colors duration-300"
                placeholder="Новий пароль"
              />
            </div>
            <div>
              <label htmlFor="confirm-password" className="sr-only">
                Підтвердіть пароль
              </label>
              <input
                id="confirm-password"
                name="confirm-password"
                type="password"
                autoComplete="new-password"
                required
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                className="appearance-none rounded-md relative block w-full px-3 py-2 border border-gray-300 dark:border-slate-700 placeholder-gray-500 dark:placeholder-slate-400 text-slate-900 dark:text-white bg-white dark:bg-slate-900 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 sm:text-sm transition-colors duration-300"
                placeholder="Підтвердіть пароль"
              />
            </div>
          </div>

          {status === "error" && (
            <p className="text-red-500 dark:text-red-400 text-sm text-center">
              {message}
            </p>
          )}

          <div>
            <button
              type="submit"
              disabled={status === "loading"}
              className="group relative w-full flex justify-center py-2 px-4 border border-transparent text-sm font-medium rounded-md text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:opacity-50 cursor-pointer transition-colors"
            >
              {status === "loading" ? "Обробка..." : "Підтвердити"}
            </button>
          </div>
        </form>
      )}
    </div>
  );
}

export default function VerifyPage() {
  return (
    <div className="flex items-center justify-center py-12 px-4 sm:px-6 lg:px-8">
      <Suspense
        fallback={
          <div className="text-slate-600 dark:text-slate-400">
            Завантаження...
          </div>
        }
      >
        <VerifyForm />
      </Suspense>
    </div>
  );
}

"use client";

import React from "react";
import { CartItem, Currency } from "../types";
import { X, ArrowLeft, Trash2, Plus, Minus } from "lucide-react";
import { DEFAULT_EXCHANGE_RATE_UAH_PER_USD } from "../constants";
import { formatCurrency } from "../utils/currency";
import { useApp } from "../context/AppContext";
import { useRouter } from "next/navigation";

const CartDrawer: React.FC = () => {
  const {
    isCartOpen: isOpen,
    setIsCartOpen,
    cart: items,
    currency,
    uahPerUsd,
    updateQuantity: onUpdateQuantity,
    removeItem: onRemoveItem,
  } = useApp();

  const router = useRouter();
  const onClose = () => setIsCartOpen(false);

  const effectiveRate =
    uahPerUsd > 0 ? uahPerUsd : DEFAULT_EXCHANGE_RATE_UAH_PER_USD;

  const getItemUsdPrice = (item: CartItem) => {
    if (item.priceUSD && item.priceUSD > 0) return item.priceUSD;
    if (item.priceUAH && item.priceUAH > 0 && effectiveRate > 0) {
      return item.priceUAH / effectiveRate;
    }
    return 0;
  };

  const formatAmount = (amount: number) => {
    return formatCurrency(amount, currency);
  };

  const formatPrice = (item: CartItem, quantity = 1) => {
    const usdPrice = getItemUsdPrice(item) * quantity;
    const amount =
      currency === Currency.USD ? usdPrice : usdPrice * effectiveRate;
    return formatAmount(amount);
  };

  const totalUSD = items.reduce(
    (sum, item) => sum + getItemUsdPrice(item) * item.quantity,
    0,
  );
  const totalDisplay =
    currency === Currency.USD ? totalUSD : totalUSD * effectiveRate;

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[70] overflow-hidden">
      <div
        className="absolute inset-0 bg-black/50 backdrop-blur-sm"
        onClick={onClose}
      />

      <div className="absolute inset-y-0 right-0 max-w-md w-full flex">
        <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 shadow-xl animate-slide-in transition-colors">
          {/* Header */}
          <div className="flex items-center justify-between px-4 py-6 border-b border-gray-100 dark:border-slate-800">
            <button
              onClick={onClose}
              className="p-2 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-full transition group"
            >
              <div className="flex items-center justify-between text-gray-500 dark:text-slate-400 group-hover:text-slate-900 dark:group-hover:text-white">
                <ArrowLeft size={24} className="mr-2" /> Повернутись до покупок
              </div>
            </button>
            <h2 className="text-lg font-bold text-gray-900 dark:text-white">
              Кошик ({items.length})
            </h2>
          </div>

          {/* Items */}
          <div className="flex-1 overflow-y-auto px-4 py-6 space-y-6">
            {items.length === 0 ? (
              <div className="text-center py-12 text-gray-500 dark:text-slate-500">
                <p>Ваш кошик порожній</p>
              </div>
            ) : (
              items.map((item) => (
                <div key={item.id} className="flex gap-4">
                  <div className="w-20 h-20 bg-gray-100 dark:bg-slate-800 rounded-md overflow-hidden flex-shrink-0">
                    <img
                      src={item.image}
                      alt={item.name}
                      className="w-full h-full object-cover"
                    />
                  </div>
                  <div className="flex-1 flex flex-col justify-between">
                    <div>
                      <h3 className="text-sm font-medium text-gray-900 dark:text-white line-clamp-2">
                        {item.name}
                      </h3>
                      <p className="text-xs text-gray-500 dark:text-slate-500 mt-1">
                        {item.category}
                      </p>
                    </div>
                    <div className="flex items-center justify-between mt-2">
                      <div className="flex items-center border border-gray-200 dark:border-slate-700 rounded-md">
                        <button
                          onClick={() => onUpdateQuantity(item.id, -1)}
                          className="p-1 hover:bg-gray-100 dark:hover:bg-slate-800 text-gray-600 dark:text-slate-400 disabled:opacity-50"
                          disabled={item.quantity <= 1}
                        >
                          <Minus size={14} />
                        </button>
                        <span className="px-2 text-sm font-medium w-8 text-center dark:text-white">
                          {item.quantity}
                        </span>
                        <button
                          onClick={() => onUpdateQuantity(item.id, 1)}
                          className="p-1 hover:bg-gray-100 dark:hover:bg-slate-800 text-gray-600 dark:text-slate-400"
                        >
                          <Plus size={14} />
                        </button>
                      </div>
                      <div className="text-sm font-bold dark:text-white">
                        {formatPrice(item, item.quantity)}
                      </div>
                    </div>
                  </div>
                  <button
                    onClick={() => onRemoveItem(item.id)}
                    className="text-gray-400 hover:text-red-500 self-start p-1"
                  >
                    <Trash2 size={18} />
                  </button>
                </div>
              ))
            )}
          </div>

          {/* Footer */}
          {items.length > 0 && (
            <div className="border-t border-gray-100 dark:border-slate-800 px-4 py-6 bg-gray-50 dark:bg-slate-800/50">
              <div className="flex justify-between items-center mb-4 text-lg font-bold text-gray-900 dark:text-white">
                <span>Всього</span>
                <span>{formatAmount(totalDisplay)}</span>
              </div>
              <p className="text-xs text-gray-500 dark:text-slate-500 mb-4 text-center">
                Вартість доставки розраховується за тарифами перевізника
              </p>
              <button
                onClick={() => {
                  onClose();
                  router.push("/checkout");
                }}
                className="w-full bg-blue-600 text-white py-3 rounded-md font-bold hover:bg-blue-800 transition shadow-md"
              >
                Оформити замовлення
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default CartDrawer;

