                  2
                </div>
                Доставка{" "}
                <span className="text-red-500 dark:text-red-400 font-bold ml-2 text-sm flex items-center gap-1">
                  <Truck size={14} /> Nova Post
                </span>
              </h2>

              <div className="space-y-4">
                {/* The Map Widget */}
