                        setDiscountValue(res.discount_value);
                        setAppliedPromoCode(res.code);
                        setPromoCodeSuccess(
                          `Промокод ${res.code} застосовано!`,
                        );
                        setPromoCodeError(null);
                      } catch (err: any) {
                        setPromoCodeError(err.message || "Недійсний промокод");
                        setPromoCodeSuccess(null);
                      }
                    }}
