                )}
              </button>

              {/* Delivery & Payment Info */}
              {deliveryInfo && (
                <div className="mt-8 bg-gray-50 dark:bg-slate-900/30 rounded-xl p-5 border border-gray-100 dark:border-slate-700 transition-colors">
