source:
"use client";

import React, {
  createContext,
  useContext,
  useState,
  useEffect,
  useMemo,
  useRef,
} from "react";
import {
  Product,
  Currency,
  CartItem,
  Category,
  StaticSeoRecord,
  Page,
  Customer,
} from "../types";
import { api } from "../services/api";
import {
  DEFAULT_EXCHANGE_RATE_UAH_PER_USD,
  DEFAULT_SETTINGS,
} from "../constants";
import { usePathname } from "next/navigation";

interface AppContextType {
  cart: CartItem[];
  addToCart: (product: Product) => void;
  updateQuantity: (id: string, delta: number) => void;
  removeItem: (id: string) => void;
  clearCart: () => void;
  isCartOpen: boolean;
  setIsCartOpen: (open: boolean) => void;
  isSidebarOpen: boolean;
  setIsSidebarOpen: (open: boolean) => void;
  currency: Currency;
  setCurrency: (currency: Currency) => void;
  theme: "light" | "dark";
  toggleTheme: () => void;
  uahPerUsd: number;
  categories: Category[];
  headerPages: Page[];
  socialLinks: {
    instagram?: string;
    telegram?: string;
    whatsapp?: string;
    viber?: string;
  };
  contactInfo: {
    email: string;
    phone: string;
    footerDescription: string;
    footerText: string;
  };
  staticSeo: Record<string, StaticSeoRecord>;
  loading: boolean;
  cartTotalUSD: number;
  cartCount: number;
  hasInternalHistory: boolean;
  isCustomerLoggedIn: boolean;
  customer: Customer | null;
  loginCustomer: (token: string) => Promise<void>;
  logoutCustomer: () => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

const CART_STORAGE_KEY = "tesla-parts-cart";
const THEME_STORAGE_KEY = "tesla-parts-theme";

const getInitialCart = (): CartItem[] => {
  if (typeof window === "undefined") return [];
  try {
    const stored = localStorage.getItem(CART_STORAGE_KEY);
    if (stored) {
      const parsed: CartItem[] = JSON.parse(stored);
      if (Array.isArray(parsed)) {
        return parsed;
      }
    }
  } catch (err) {
    console.warn("Failed to load cart from storage", err);
  }
  return [];
};

const getInitialTheme = (): "light" | "dark" => {
  if (typeof window === "undefined") return "light";
  const stored = localStorage.getItem(THEME_STORAGE_KEY);
  if (stored === "light" || stored === "dark") return stored;
  return window.matchMedia("(prefers-color-scheme: dark)").matches
    ? "dark"
    : "light";
};

const getProductUsdPrice = (product: Product, rate: number): number => {
  if (product.priceUSD && product.priceUSD > 0) {
    return product.priceUSD;
  }
  if (product.priceUAH && product.priceUAH > 0 && rate > 0) {
    return product.priceUAH / rate;
  }
  return 0;
};

const compareBySortOrder = <
  T extends { sort_order?: number | null; id?: number },
>(
  a: T,
  b: T,
) => {
  const orderDiff = (b.sort_order ?? 0) - (a.sort_order ?? 0);
  if (orderDiff !== 0) return orderDiff;
  if (a.id !== undefined && b.id !== undefined) {
    return a.id - b.id;
  }
  return 0;
};

const sortSubcategoryTreeData = (subs?: any[]): any[] => {
  if (!subs) return [];
  return [...subs].sort(compareBySortOrder).map((sub) => ({
    ...sub,
    subcategories: sortSubcategoryTreeData(sub.subcategories),
  }));
};

const sortCategoryTreeData = (cats: Category[]): Category[] => {
  return [...cats].sort(compareBySortOrder).map((cat) => ({
    ...cat,
    subcategories: sortSubcategoryTreeData(cat.subcategories),
  }));
};

// --- Image Preloader ---
const preloadImages = async (imageUrls: (string | undefined)[]) => {
  if (typeof window === "undefined") return;
  const promises = imageUrls.filter(Boolean).map((src) => {
    return new Promise((resolve) => {
      const img = new Image();
      img.src = src!;
      img.onload = resolve;
      img.onerror = resolve;
    });
  });
  await Promise.all(promises);
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({
  children,
}) => {
  const pathname = usePathname();
  const [historyCount, setHistoryCount] = useState(0);

  useEffect(() => {
    setHistoryCount((prev) => prev + 1);
  }, [pathname]);

  const hasInternalHistory = historyCount > 1;

  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [currency, setCurrency] = useState<Currency>(Currency.UAH);
  const [theme, setTheme] = useState<"light" | "dark">("light");
  const [uahPerUsd, setUahPerUsd] = useState(DEFAULT_EXCHANGE_RATE_UAH_PER_USD);
  const [categories, setCategories] = useState<Category[]>([]);
  const [headerPages, setHeaderPages] = useState<Page[]>([]);
  const [socialLinks, setSocialLinks] = useState<{
    instagram?: string;
    telegram?: string;
    whatsapp?: string;
    viber?: string;
  }>({
    instagram: "",
    telegram: "",
    whatsapp: "",
    viber: "",
  });
  const [contactInfo, setContactInfo] = useState({
    email: "",
    phone: "",
    footerDescription: "",
    footerText: "",
  });
  const [staticSeo, setStaticSeo] = useState<Record<string, StaticSeoRecord>>(
    {},
  );
  const [loading, setLoading] = useState(true);
  const [isCustomerLoggedIn, setIsCustomerLoggedIn] = useState(false);
  const [customer, setCustomer] = useState<Customer | null>(null);

  // Load initial state on mount
  useEffect(() => {
    const initApp = async () => {
      setCart(getInitialCart());
      setTheme(getInitialTheme());

      const token = localStorage.getItem("customerToken");
      if (token) {
        setIsCustomerLoggedIn(true);
        try {
          const [serverCart, customerData] = await Promise.all([
            api.getCart(),
            api.getMe(),
          ]);
          setCart(serverCart);
          setCustomer(customerData);
        } catch (err) {
          console.error(
            "Failed to fetch initial customer or cart from server",
            err,
          );
        }
      }

      // Close sidebar on mobile initially
      if (typeof window !== "undefined" && window.innerWidth < 1024) {
        setIsSidebarOpen(false);
      }
    };
    initApp();
  }, []);

  useEffect(() => {
    const handleLogoutEvent = () => {
      setIsCustomerLoggedIn(false);
      setCustomer(null);
      setCart([]);
      if (typeof window !== "undefined") {
        localStorage.removeItem(CART_STORAGE_KEY);
      }
    };
    window.addEventListener("customer-logged-out", handleLogoutEvent);
    return () => {
      window.removeEventListener("customer-logged-out", handleLogoutEvent);
    };
  }, []);

  const loginCustomer = async (token: string) => {
    localStorage.setItem("customerToken", token);
    setIsCustomerLoggedIn(true);

    try {
      const [serverCart, customerData] = await Promise.all([
        api.getCart(),
        api.getMe(),
      ]);
      setCustomer(customerData);
      const guestCart = cart;

      if (guestCart.length > 0) {
        // Merge guest cart with server cart
        const merged = [...serverCart];
        guestCart.forEach((guestItem) => {
          const existingIdx = merged.findIndex((i) => i.id === guestItem.id);
          if (existingIdx > -1) {
            merged[existingIdx].quantity =
              merged[existingIdx].quantity + guestItem.quantity;
          } else {
            merged.push(guestItem);
          }
        });

        setCart(merged);
        await api.saveCart(merged);
      } else {
        setCart(serverCart);
      }
    } catch (err) {
      console.error("Failed to merge cart on login", err);
    }
  };

  const logoutCustomer = () => {
    localStorage.removeItem("customerToken");
    setIsCustomerLoggedIn(false);
    setCustomer(null);
    setCart([]);
    localStorage.removeItem(CART_STORAGE_KEY);
  };

  // Theme application and system listener
  useEffect(() => {
    // Apply theme class to document
    if (theme === "dark") {
      document.documentElement.classList.add("dark");
    } else {
      document.documentElement.classList.remove("dark");
    }

    // Listen for system theme changes
    const mediaQuery = window.matchMedia("(prefers-color-scheme: dark)");
    const handleChange = (e: MediaQueryListEvent) => {
      // ONLY auto-adjust if there is no manual preference in localStorage
      const manualPreference = localStorage.getItem(THEME_STORAGE_KEY);
      if (!manualPreference) {
        setTheme(e.matches ? "dark" : "light");
      }
    };

    mediaQuery.addEventListener("change", handleChange);
    return () => mediaQuery.removeEventListener("change", handleChange);
  }, [theme]);

  const toggleTheme = () => {
    const newTheme = theme === "light" ? "dark" : "light";
    setTheme(newTheme);
    // Explicitly save manual preference
    localStorage.setItem(THEME_STORAGE_KEY, newTheme);
  };

  // Save cart to local storage on changes
  useEffect(() => {
    if (
      cart.length > 0 ||
      (typeof window !== "undefined" && localStorage.getItem(CART_STORAGE_KEY))
    ) {
      localStorage.setItem(CART_STORAGE_KEY, JSON.stringify(cart));
    }
  }, [cart]);

  // Sync cart to server on changes if logged in (debounced to avoid race conditions)
  useEffect(() => {
    if (!isCustomerLoggedIn) return;

    const timer = setTimeout(async () => {
      try {
        await api.saveCart(cart);
      } catch (err) {
        console.error("Failed to sync cart to server", err);
      }
    }, 500);

    return () => clearTimeout(timer);
  }, [cart, isCustomerLoggedIn]);

  useEffect(() => {
    const loadData = async () => {
      try {
        const headerPageSlugs = [
          "about",
          "delivery",
          "returns",
          "contacts",
          "faq",
          "terms-of-service",
          "privacy-policy",
        ];
        const [categoriesData, socialLinksData, pagesData, staticSeoData] =
          await Promise.all([
            api.getCategories(),
            api.getSocialLinks(),
            api.getPagesBySlugs(headerPageSlugs),
            api.getStaticSeo(),
          ]);

        const sortedCats = sortCategoryTreeData(categoriesData);
        setCategories(sortedCats);
        setSocialLinks(socialLinksData);
        setHeaderPages(pagesData);

        const seoMap: Record<string, StaticSeoRecord> = {};
        staticSeoData.forEach((record) => {
          seoMap[record.slug] = record;
        });
        setStaticSeo(seoMap);

        // Preload critical images
        const heroImages = sortedCats.slice(0, 4).map((c) => c.image);
        await preloadImages(heroImages);
      } catch (e) {
        console.error("Failed to load initial data", e);
      } finally {
        setLoading(false);
      }
    };
    loadData();
  }, []);

  useEffect(() => {
    const fetchRate = async () => {
      try {
        const value = await api.getSetting("exchange_rate");
        const parsed = value ? parseFloat(value) : NaN;
        if (!Number.isNaN(parsed) && parsed > 0) {
          setUahPerUsd(parsed);
        }
      } catch (e) {
        console.error("Failed to load exchange rate", e);
      }
    };
    fetchRate();
  }, []);

  useEffect(() => {
    const loadContactInfo = async () => {
      const fetchSetting = async (key: string, defaultValue: string) => {
        try {
          const value = await api.getSetting(key);
          return value || defaultValue;
        } catch {
          return defaultValue;
        }
      };
      const [email, phone, footerDescription, footerText] = await Promise.all([
        fetchSetting("contact_email", DEFAULT_SETTINGS.contact_email),
        fetchSetting("contact_phone", DEFAULT_SETTINGS.contact_phone),
        fetchSetting("footer_description", DEFAULT_SETTINGS.footer_description),
        fetchSetting("footer_text", DEFAULT_SETTINGS.footer_text),
      ]);
      setContactInfo({
        email,
        phone,
        footerDescription,
        footerText,
      });
    };
    loadContactInfo();
  }, []);

  const addToCart = (product: Product) => {
    setCart((prev) => {
      const existing = prev.find((item) => item.id === product.id);
      if (existing) {
        return prev.map((item) =>
          item.id === product.id
            ? { ...item, quantity: item.quantity + 1 }
            : item,
        );
      }
      return [...prev, { ...product, quantity: 1 }];
    });
    setIsCartOpen(true);
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart((prev) =>
      prev.map((item) => {
        if (item.id === id) {
          return { ...item, quantity: Math.max(1, item.quantity + delta) };
        }
        return item;
      }),
    );
  };

  const removeItem = (id: string) => {
    setCart((prev) => prev.filter((item) => item.id !== id));
  };

  const clearCart = () => setCart([]);

  const cartTotalUSD = useMemo(() => {
    const effectiveRate =
      uahPerUsd > 0 ? uahPerUsd : DEFAULT_EXCHANGE_RATE_UAH_PER_USD;
    return cart.reduce((sum, item) => {
      const priceUSD = getProductUsdPrice(item, effectiveRate);
      return sum + priceUSD * item.quantity;
    }, 0);
  }, [cart, uahPerUsd]);

  const cartCount = useMemo(
    () => cart.reduce((sum, item) => sum + item.quantity, 0),
    [cart],
  );

  return (
    <AppContext.Provider
      value={{
        cart,
        addToCart,
        updateQuantity,
        removeItem,
        clearCart,
        isCartOpen,
        setIsCartOpen,
        isSidebarOpen,
        setIsSidebarOpen,
        currency,
        setCurrency,
        theme,
        toggleTheme,
        uahPerUsd,
        categories,
        headerPages,
        socialLinks,
        contactInfo,
        staticSeo,
        loading,
        cartTotalUSD,
        cartCount,
        hasInternalHistory,
        isCustomerLoggedIn,
        customer,
        loginCustomer,
        logoutCustomer,
      }}
    >
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (context === undefined) {
    throw new Error("useApp must be used within an AppProvider");
  }
  return context;
};

import {
  Product,
  OrderData,
  Category,
  StaticSeoRecord,
  Page,
  OrderRead,
  CartItem,
} from "../types";

const getApiUrl = () => {
  if (typeof window === "undefined") {
    // Server-side (SSR): Connect directly to backend container in Docker network
    return "http://backend:8000";
  }
  // Client-side (Browser): Connect to public API URL
  return process.env.NEXT_PUBLIC_API_URL || "https://api.teslafix.com.ua";
};

const API_URL = getApiUrl();

export interface ProductFilter {
  category?: string;
  subId?: number;
  limit?: number;
  offset?: number;
  search?: string;
  is_favourite?: boolean;
}

const slugify = (value: string) =>
  value.toLowerCase().trim().replace(/\s+/g, "-");

const handleAuthResponse = (res: Response) => {
  if (res.status === 401 || res.status === 403) {
    if (typeof window !== "undefined") {
      localStorage.removeItem("customerToken");
      window.dispatchEvent(new Event("customer-logged-out"));
    }
  }
};

export const api = {
  getProducts: async (filters: ProductFilter = {}): Promise<Product[]> => {
    const params = new URLSearchParams();
    if (filters.category) params.append("category_slug", filters.category);
    if (filters.subId)
      params.append("subcategory_id", filters.subId.toString());
    if (filters.limit) params.append("limit", filters.limit.toString());
    if (filters.offset) params.append("offset", filters.offset.toString());
    if (filters.search) params.append("search", filters.search);
    if (filters.is_favourite !== undefined)
      params.append("is_favourite", filters.is_favourite.toString());

    const res = await fetch(`${API_URL}/products/?${params.toString()}`);
    if (!res.ok) throw new Error("Failed to fetch products");
    return res.json();
  },

  getProduct: async (id: string): Promise<Product> => {
    const res = await fetch(`${API_URL}/products/${id}`);
    if (!res.ok) throw new Error("Failed to fetch product");
    return res.json();
  },

  getLabels: async (): Promise<string[]> => {
    const res = await fetch(`${API_URL}/products/labels`);
    if (!res.ok) throw new Error("Failed to fetch labels");
    return res.json();
  },

  getCategories: async (): Promise<Category[]> => {
    const res = await fetch(`${API_URL}/categories/`);
    if (!res.ok) throw new Error("Failed to fetch categories");
    return res.json();
  },

  getCategory: async (id: number): Promise<Category> => {
    const res = await fetch(`${API_URL}/categories/${id}`);
    if (!res.ok) throw new Error("Failed to fetch category details");
    return res.json();
  },

  createOrder: async (orderData: OrderData) => {
    const payload = {
      items: orderData.items,
      totalUSD: orderData.totalUSD,
      customer: orderData.customer,
      delivery: orderData.delivery,
      paymentMethod: orderData.paymentMethod,
    };

    const token = localStorage.getItem("customerToken");
    const headers: Record<string, string> = {
      "Content-Type": "application/json",
    };
    if (token) {
      headers["Authorization"] = `Bearer ${token}`;
    }

    const res = await fetch(`${API_URL}/orders/`, {
      method: "POST",
      headers,
      body: JSON.stringify(payload),
    });

    handleAuthResponse(res);

    if (!res.ok) throw new Error("Failed to create order");
    return res.json();
  },

  getPage: async (slug: string): Promise<Page | null> => {
    try {
      const res = await fetch(`${API_URL}/pages/${slug}`);
      if (!res.ok) return null;
      return res.json();
    } catch {
      return null;
    }
  },

  getPagesBySlugs: async (slugs: string[]): Promise<Page[]> => {
    const res = await fetch(`${API_URL}/pages/by-slugs`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ slugs }),
    });
    if (!res.ok) throw new Error("Failed to fetch pages");
    return res.json();
  },

  getSetting: async (key: string): Promise<string | null> => {
    try {
      const res = await fetch(`${API_URL}/settings/${key}`);
      if (!res.ok) return null;
      const data = await res.json();
      return data.value;
    } catch {
      return null;
    }
  },

  getSocialLinks: async (): Promise<{
    instagram?: string;
    telegram?: string;
    whatsapp?: string;
    viber?: string;
  }> => {
    const res = await fetch(`${API_URL}/settings/social-links`);
    if (!res.ok) throw new Error("Failed to fetch social links");
    return res.json();
  },

  getStaticSeo: async (): Promise<StaticSeoRecord[]> => {
    const res = await fetch(`${API_URL}/seo/static`);
    if (!res.ok) throw new Error("Failed to fetch static SEO data");
    return res.json();
  },

  getFeedback: async (): Promise<any[]> => {
    const res = await fetch(`${API_URL}/feedback/`);
    if (!res.ok) throw new Error("Failed to fetch feedback");
    return res.json();
  },

  registerCustomer: async (email: string) => {
    const res = await fetch(`${API_URL}/customers/register`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email }),
    });
    if (!res.ok) {
      const error = await res.json();
      throw new Error(error.detail || "Failed to register");
    }
    return res.json();
  },

  forgotPassword: async (email: string) => {
    const res = await fetch(`${API_URL}/customers/forgot-password`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email }),
    });
    if (!res.ok) {
      const error = await res.json();
      throw new Error(error.detail || "Failed to request password reset");
    }
    return res.json();
  },

  resetPassword: async (data: any) => {
    const res = await fetch(`${API_URL}/customers/reset-password`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(data),
    });
    if (!res.ok) {
      const error = await res.json();
      throw new Error(error.detail || "Failed to reset password");
    }
    return res.json();
  },

  verifyCustomer: async (data: any) => {
    const res = await fetch(`${API_URL}/customers/verify`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(data),
    });
    if (!res.ok) {
      const error = await res.json();
      throw new Error(error.detail || "Failed to verify");
    }
    return res.json();
  },

  loginCustomer: async (data: any) => {
    const res = await fetch(`${API_URL}/customers/login`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(data),
    });
    if (!res.ok) {
      const error = await res.json();
      throw new Error(error.detail || "Failed to login");
    }
    return res.json();
  },

  getMe: async () => {
    const token = localStorage.getItem("customerToken");
    if (!token) throw new Error("Not authenticated");
    const res = await fetch(`${API_URL}/customers/me`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    handleAuthResponse(res);
    if (!res.ok) throw new Error("Failed to fetch user info");
    return res.json();
  },

  getMyOrders: async (): Promise<OrderRead[]> => {
    const token = localStorage.getItem("customerToken");
    if (!token) throw new Error("Not authenticated");
    const res = await fetch(`${API_URL}/orders/my`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    handleAuthResponse(res);
    if (!res.ok) throw new Error("Failed to fetch orders");
    return res.json();
  },

  getCart: async (): Promise<CartItem[]> => {
    const token = localStorage.getItem("customerToken");
    if (!token) return [];
    const res = await fetch(`${API_URL}/customers/cart`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    handleAuthResponse(res);
    if (!res.ok) throw new Error("Failed to fetch cart");
    return res.json();
  },

  saveCart: async (cartItems: CartItem[]): Promise<any> => {
    const token = localStorage.getItem("customerToken");
    if (!token) return null;
    const res = await fetch(`${API_URL}/customers/cart`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify(cartItems),
    });
    handleAuthResponse(res);
    if (!res.ok) throw new Error("Failed to save cart");
    return res.json();
  },

  updateProfile: async (data: {
    first_name: string;
    last_name: string;
    phone: string;
    default_address?: string;
  }): Promise<any> => {
    const token = localStorage.getItem("customerToken");
    if (!token) throw new Error("Not authenticated");
    const res = await fetch(`${API_URL}/customers/profile`, {
      method: "PUT",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify(data),
    });
    handleAuthResponse(res);
    if (!res.ok) {
      const err = await res.json();
      throw new Error(err.detail || "Failed to update profile");
    }
    return res.json();
  },

  validatePromoCode: async (
    code: string,
  ): Promise<{
    code: string;
    discount_type: "percent" | "usd" | "uah";
    discount_value: number;
    valid: boolean;
  }> => {
    const token = localStorage.getItem("customerToken");
    const headers: Record<string, string> = {
      "Content-Type": "application/json",
    };
    if (token) {
      headers["Authorization"] = `Bearer ${token}`;
    }
    const res = await fetch(`${API_URL}/promocodes/validate`, {
      method: "POST",
      headers,
      body: JSON.stringify({ code }),
    });

    handleAuthResponse(res);

    if (!res.ok) {
      const err = await res.json();
      throw new Error(err.detail || "Недійсний промокод");
    }
    return res.json();
  },
};
